import {
  AbiCoder,
  concat,
  getBytes,
  getBytesCopy,
  getCreate2Address,
  hexlify,
  id,
  Interface,
  keccak256,
  toBigInt,
  ZeroHash,
  zeroPadValue,
  type BytesLike,
} from "ethers";

import { address as singletonFactoryAddress } from "./erc2470Factory.js";
import { address as moduleProxyFactoryAddress } from "./proxyFactory.js";

export const bytecode =
  "";
export const salt = ZeroHash;

export const iface = new Interface([
  "function createAndSetupModule(address mastercopy, bytes initializer, bytes[] setupCalls, bytes32 saltNonce) returns (address)",
]);

export const address = getCreate2Address(
  singletonFactoryAddress,
  salt,
  keccak256(bytecode)
);

/**
 * Predicts a module address from its initializer, setup calls and salt nonce.
 * `initializer` names the module's final owner, as passed to the factory.
 */
export function predictModuleAddress({
  mastercopy,
  initializer,
  setupCalls,
  saltNonce,
}: {
  mastercopy: string;
  initializer: BytesLike;
  setupCalls: BytesLike[];
  saltNonce: BytesLike;
}): string {
  const coder = AbiCoder.defaultAbiCoder();
  const deploymentNonce = keccak256(
    coder.encode(
      ["bytes32", "bytes32", "bytes32"],
      [
        keccak256(initializer),
        keccak256(coder.encode(["bytes[]"], [setupCalls])),
        saltNonce,
      ]
    )
  );

  return getCreate2Address(
    moduleProxyFactoryAddress,
    keccak256(
      concat([keccak256(patchInitializer(initializer)), deploymentNonce])
    ),
    keccak256(
      concat([
        "0x602d8060093d393df3363d3d373d3d3d363d73",
        mastercopy,
        "0x5af43d82803e903d91602b57fd5bf3",
      ])
    )
  );
}

/**
 * The initializer the factory deploys with: itself in place of the owner, the
 * first word of the `setUp(bytes)` parameters at 0x44.
 */
function patchInitializer(initializer: BytesLike): string {
  const patched = getBytesCopy(initializer);
  if (
    patched.length < 4 + 3 * 32 ||
    hexlify(patched.subarray(0, 4)) !== setUpSelector ||
    toBigInt(patched.subarray(0x04, 0x24)) !== 0x20n
  ) {
    throw new Error("Initializer must be setUp(bytes) starting with an owner");
  }
  patched.set(getBytes(zeroPadValue(address, 32)), 0x44);

  return hexlify(patched);
}

const setUpSelector = id("setUp(bytes)").slice(0, 10);
